import { Button, ThemeScope, ToastRegion, toast } from '@strata/react';

// Mount once, inside your ThemeScope (e.g. in the root layout).
export function App({ children }: { children: React.ReactNode }) {
  return (
    <ThemeScope theme="vela">
      {children}
      <ToastRegion />
    </ThemeScope>
  );
}

export function SaveButton() {
  return <Button onPress={() => toast({ title: 'Changes saved', tone: 'success' })}>Save</Button>;
}
